import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第四十六卦 升 地风升 坤上巽下","description":"周易 - 第四十六卦 升 地风升 坤上巽下","frontmatter":{"title":"第四十六卦 升 地风升 坤上巽下","description":"周易 - 第四十六卦 升 地风升 坤上巽下"},"headers":[],"relativePath":"zh/classics/zhouyi/047.md","filePath":"zh/classics/zhouyi/047.md"}'),l={name:"zh/classics/zhouyi/047.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="升" tabindex="-1">升 <a class="header-anchor" href="#升" aria-label="Permalink to “升”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>元亨，用见大人，勿恤，南征吉。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>柔以时升，巽而顺，刚中而应，是以大亨。用见大人，勿恤；有庆也。南征吉，志行也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>地中生木，升；君子以顺德，积小以高大。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>允升，大吉。象曰：允升大 吉，上合志也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>孚乃利用禴，无咎。象曰：九二之孚，有喜也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>升虚邑。象曰：升虚邑，无所疑也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>王用亨于岐山，吉无咎。象曰：王用亨于岐山，顺事也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>贞吉，升阶。象曰：贞吉升阶，大得志也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>冥升，利于不息之贞。象曰：冥升在上，消不富也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
